    <div class="admin-question-timer-bottom"><span id="adminTimerStatus">${limit?'Ожидание таймера':'Без ограничения времени'}</span><span id="adminTimerLimit">${limit?`из ${formatAdminClock(limit)}`:'ТАЙМЕР ОТКЛЮЧЁН'}</span></div>
