function formatAdminClock(total){const sec=Math.max(0,Math.floor(Number(total)||0));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function syncAdminTimerFromState(state){
  const q=state?.current_question;
  adminTimerSnapshot={limit:Math.max(0,Number(q?.time_limit||0)),remaining:state?.timer_remaining==null?null:Math.max(0,Number(state.timer_remaining)),receivedAt:performance.now(),revealed:!!state?.answers_revealed,hasQuestion:!!q};
  updateAdminQuestionTimer();
}
function updateAdminQuestionTimer(){
  const box=$('adminQuestionTimer');if(!box)return;
  const snap=adminTimerSnapshot,limit=snap.limit;
  box.classList.toggle('is-revealed',snap.revealed);
  if(!limit){$('adminTimerValue').textContent='∞';$('adminTimerStatus').textContent='Без ограничения времени';$('adminTimerLimit').textContent='ТАЙМЕР ОТКЛЮЧЁН';$('adminTimerFill').style.width='100%';box.classList.remove('is-urgent');return;}
  const base=snap.remaining==null?limit:snap.remaining;
  const elapsed=snap.revealed?0:Math.max(0,(performance.now()-snap.receivedAt)/1000);
  const remaining=Math.max(0,Math.ceil(base-elapsed));
  const pct=Math.max(0,Math.min(100,(remaining/limit)*100));
  $('adminTimerValue').textContent=formatAdminClock(remaining);
  $('adminTimerStatus').textContent=snap.revealed?'Ответы открыты · таймер остановлен':remaining===0?'Время вышло':'Осталось до окончания вопроса';
  $('adminTimerLimit').textContent=`из ${formatAdminClock(limit)}`;
  $('adminTimerFill').style.width=`${pct}%`;
  box.classList.toggle('is-urgent',remaining>0&&remaining<=10&&!snap.revealed);
}
