function roundMediaType(){const type=$('roundType').value;return type==='karaoke'?'video':type==='gallery'?'visual':'';}
function renderRoundMediaChecklist(){
  const type=$('roundType').value,host=$('roundMediaItems');if(!host)return;
  const allowed=roundMediaCache.filter(x=>type==='karaoke'?x.type==='video':['video','image'].includes(x.type));
  const selected=roundMediaSelection.map(url=>roundMediaCache.find(x=>x.url===url)).filter(x=>x&&allowed.some(y=>y.url===x.url));
  host.innerHTML=`<div class="round-media-available">${allowed.map(x=>`<label class="round-media-option"><input type="checkbox" data-media-url="${esc(x.url)}" ${roundMediaSelection.includes(x.url)?'checked':''}><span class="round-media-type">${x.type==='video'?'▶':'▧'}</span><span><b>${esc(x.name)}</b><small>${x.type.toUpperCase()} · ${(x.size/1024/1024).toFixed(1)} МБ</small></span></label>`).join('')||'<p class="muted">Подходящих файлов нет — загрузите их в медиатеку.</p>'}</div><div class="round-media-order"><b>Порядок показа · ${selected.length} файлов</b>${selected.map((x,i)=>`<div class="round-media-order-row"><span>${i+1}</span><b>${esc(x.name)}</b><div><button type="button" class="icon-btn" data-move-url="${esc(x.url)}" data-direction="-1" ${i===0?'disabled':''}>↑</button><button type="button" class="icon-btn" data-move-url="${esc(x.url)}" data-direction="1" ${i===selected.length-1?'disabled':''}>↓</button></div></div>`).join('')||'<small class="muted">Отметьте несколько файлов выше.</small>'}</div>`;
  host.querySelectorAll('[data-media-url]').forEach(el=>el.addEventListener('change',()=>toggleRoundMedia(el.dataset.mediaUrl,el.checked)));
  host.querySelectorAll('[data-move-url]').forEach(el=>el.addEventListener('click',()=>moveRoundMedia(el.dataset.moveUrl,Number(el.dataset.direction))));
}
function toggleRoundMedia(url,checked){if(checked){if(!roundMediaSelection.includes(url))roundMediaSelection.push(url);}else roundMediaSelection=roundMediaSelection.filter(x=>x!==url);renderRoundMediaChecklist();}
function moveRoundMedia(url,direction){const i=roundMediaSelection.indexOf(url),j=i+direction;if(i<0||j<0||j>=roundMediaSelection.length)return;[roundMediaSelection[i],roundMediaSelection[j]]=[roundMediaSelection[j],roundMediaSelection[i]];renderRoundMediaChecklist();}
function updateRoundMediaField(selected=[]){const type=$('roundType').value,mediaType=roundMediaType(),field=$('roundMediaField');field.classList.toggle('hidden',!mediaType);$('roundGallerySettings').classList.toggle('hidden',type!=='gallery');$('roundKaraokeSettings').classList.toggle('hidden',type!=='karaoke');$('roundMicHelp').classList.toggle('hidden',type!=='mic');$('roundWheelSettings').classList.toggle('hidden',type!=='wheel');if(!mediaType){roundMediaSelection=[];return;}if(selected.length||!roundMediaSelection.length)roundMediaSelection=selected.slice();const allowedUrls=new Set(roundMediaCache.filter(x=>type==='karaoke'?x.type==='video':['video','image'].includes(x.type)).map(x=>x.url));roundMediaSelection=roundMediaSelection.filter(url=>allowedUrls.has(url));$('roundMediaLabel').textContent=type==='karaoke'?'Видеофайлы для караоке':'Фотографии и видео для показа';$('roundMediaHelp').textContent=type==='karaoke'?'Отметьте несколько видео и задайте порядок стрелками. После окончания клипа система оценит выступление.':'Отметьте несколько фотографий и видео. Настройте интервал автоматической смены или переключайте материалы вручную.';renderRoundMediaChecklist();}
