function questionTypeChanged(){let t=$('questionType').value,optsEl=$('questionOptions'),opts=optsEl.value.split('\n').map(x=>x.trim()).filter(Boolean),old=$('questionCorrect').value;$('optionsField').classList.toggle('hidden',!['single_choice','multiple_choice','true_false'].includes(t));if(t==='true_false'&&(!opts.length||opts.join('|')!=='Верно|Неверно')){opts=['Верно','Неверно'];optsEl.value=opts.join('\n')}let field=$('correctField');if(['single_choice','true_false'].includes(t)){field.innerHTML='<label>Правильный вариант</label><select id="questionCorrectSelect" onchange="document.getElementById(\'questionCorrect\').value=this.value"><option value="">Выберите правильный ответ</option>'+opts.map(o=>`<option value="${esc(o)}" ${o===old?'selected':''}>${esc(o)}</option>`).join('')+'</select>'}else if(t==='multiple_choice'){let selected=old.split(',').map(x=>x.trim());field.innerHTML='<label>Отметьте все правильные варианты</label><div class="correct-option-list">'+opts.map((o,i)=>`<label><input type="checkbox" class="correct-option-check" value="${esc(o)}" ${selected.includes(o)?'checked':''} onchange="document.getElementById('questionCorrect').value=[...document.querySelectorAll('.correct-option-check:checked')].map(x=>x.value).join(', ')"><span>${esc(o)}</span></label>`).join('')+'</div>'}else{field.innerHTML='<label>Эталонный ответ</label><input id="questionCorrectText" value="'+esc(old)+'" placeholder="Введите правильный ответ">'}}
async function saveQuestion(){let id=Number($('questionId').value),q=id?findQ(id):null,sel=$('questionCorrectSelect'),checks=[...document.querySelectorAll('.correct-option-check:checked')],correct=checks.length?checks.map(x=>x.value).join(', '):(sel?[...sel.selectedOptions].map(x=>x.value).join(', '):($('questionCorrectText')?.value||$('questionCorrect').value||''));$('questionCorrect').value=correct;let data={title:$('questionTitle').value.trim(),body:$('questionBody').value,question_type:$('questionType').value,points:Number($('questionPoints').value||0),time_limit:Number($('questionTime').value||0),correct_answer:correct,options:$('questionOptions').value.split('\n').map(x=>x.trim()).filter(Boolean),explanation:$('questionExplanation').value,media:q?.media||'',media_type:q?.media_type||''};if(['single_choice','multiple_choice','true_false'].includes(data.question_type)&&!correct)return alert('Выберите правильный ответ.');$('questionDialog').close();if(id)await act('update_question',{...data,question_id:id});else await act('add_question',{...data,round_id:Number($('questionRoundId').value)})}
