async function detachQuestionMedia(){const id=Number($('questionId').value),q=id?findQ(id):null;if(!q)return alert('Сначала сохраните вопрос.');if(!confirm('Открепить медиафайл от этого вопроса? Сам файл останется в медиатеке.'))return;const data={question_id:id,title:q.title,body:q.body,points:q.points,media:'',media_type:'',question_type:q.question_type,options:q.options,correct_answer:q.correct_answer,explanation:q.explanation,time_limit:q.time_limit,required:q.required};await api('/api/admin/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update_question',data})});$('questionMediaInfo').textContent='Медиафайл не прикреплён';$('detachQuestionMedia').classList.add('hidden');await refresh();await loadMediaLibrary();}
async function loadMediaLibrary(){
  const host=$('mediaLibraryList');if(!host)return;
  try{
    const items=await api('/api/admin/media');
    host.innerHTML=items.map(x=>{
      const active=S?.screen_mode==='media_fullscreen'&&S.screen_media?.url===x.url;
      const preview=x.type==='audio'?`<audio controls preload="none" src="${esc(x.url)}"></audio>`:x.type==='video'?`<video controls muted preload="metadata" playsinline src="${esc(x.url)}"></video>`:`<img src="${esc(x.url)}" alt="${esc(x.name)}">`;
      const showButton=['image','video'].includes(x.type)?(active?'<span class="media-on-screen">● Сейчас на экране</span>':`<button class="btn tiny primary" onclick="showScreenMedia('${esc(x.url)}','${esc(x.name)}','${x.type}')">⛶ На весь экран</button>`):'';
      return `<article class="media-library-item"><div class="media-library-preview">${preview}</div><div class="media-library-info"><b>${esc(x.name)}</b><small>${x.type.toUpperCase()} · ${(x.size/1024/1024).toFixed(2)} МБ</small><small>${x.references.length?`Прикреплён: ${x.references.map(r=>esc(r.round_title)+' / '+esc(r.title)).join('; ')}`:'Не прикреплён'}</small>${showButton}</div><div class="media-library-actions"><select id="attach-${esc(x.filename||x.name)}"><option value="">Прикрепить к вопросу…</option>${S.rounds.flatMap(r=>r.questions.map(q=>`<option value="${q.id}">${esc(r.title)} — ${esc(q.title||'Вопрос '+q.id)}</option>`)).join('')}</select><button class="btn tiny secondary" onclick="renameLibraryMedia('${encodeURIComponent(x.filename||x.name)}','${encodeURIComponent(x.name)}')">Переименовать</button><button class="btn tiny secondary" onclick="attachLibraryMedia('${esc(x.filename||x.name)}','${esc(x.url)}','${x.type}')">Прикрепить</button><button class="btn tiny danger-glass" onclick="deleteLibraryMedia('${esc(x.filename||x.name)}')">Удалить</button></div></article>`;
    }).join('')||'<div class="empty-state">Медиатека пока пуста. Загрузите первый файл.</div>';
  }catch(e){host.textContent=e.message;}
}
async function attachLibraryMedia(name,url,type){const sel=$('attach-'+name),qid=Number(sel?.value),q=findQ(qid);if(!q)return alert('Выберите вопрос.');await api('/api/admin/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update_question',data:{question_id:qid,title:q.title,body:q.body,points:q.points,media:url,media_type:type,question_type:q.question_type,options:q.options,correct_answer:q.correct_answer,explanation:q.explanation,time_limit:q.time_limit,required:q.required}})});await refresh();await loadMediaLibrary();}
async function renameLibraryMedia(filename,current){filename=decodeURIComponent(filename);current=decodeURIComponent(current);const value=prompt('Название файла в медиатеке:',current||'');if(value===null)return;const display_name=value.trim();if(!display_name)return alert('Название не может быть пустым.');try{await api('/api/admin/media/rename',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename,display_name})});await loadMediaLibrary();if($('roundDialog')?.open){const keep=roundMediaSelection.slice();await loadRoundMediaCache();roundMediaSelection=keep;renderRoundMediaChecklist();}}catch(e){alert(e.message)}}
async function deleteLibraryMedia(name){if(!confirm('Удалить файл из медиатеки? Файл нельзя удалить, пока он прикреплён к вопросам.'))return;try{await api('/api/admin/media/'+encodeURIComponent(name),{method:'DELETE'});await loadMediaLibrary()}catch(e){alert(e.message)}}
function toggleMediaDrawer(force){const drawer=$('mediaDrawer'),backdrop=$('mediaDrawerBackdrop');if(!drawer)return;const open=typeof force==='boolean'?force:!drawer.classList.contains('open');drawer.classList.toggle('open',open);backdrop.classList.toggle('open',open);document.body.classList.toggle('media-drawer-open',open);if(open)loadMediaLibrary();}
async function showScreenMedia(url,name,type){if(!['image','video'].includes(type))return alert('На весь экран можно вывести изображение или видео.');await act('show_screen_media',{url,name,type});await loadMediaLibrary();}
async function hideScreenMedia(){await act('hide_screen_media',{});await loadMediaLibrary();}
function renderMediaPresentationControls(){
  const host=$('mediaPresentationControls');if(!host||!S)return;
  const active=S.screen_mode==='media_fullscreen'&&S.screen_media;
  if(!active){host.innerHTML='<div class="media-presentation-idle"><b>Главный экран свободен</b><small>Выберите изображение или видео в каталоге и нажмите «На весь экран».</small></div>';return;}
  const m=S.screen_media,control=S.media_control||{},matches=control.scope==='screen'&&control.url===m.url,playback=matches?control.action:'stopped';
  const controls=m.type==='video'?`<div class="media-control-actions"><button class="btn primary" onclick="act('media_play',{})">▶ ${playback==='paused'?'Продолжить':'Воспроизвести'}</button><button class="btn secondary" ${playback!=='playing'?'disabled':''} onclick="act('media_pause',{})">Ⅱ Пауза</button><button class="btn secondary" onclick="act('media_restart',{})">↻ С начала</button><button class="btn danger-glass" ${playback==='stopped'?'disabled':''} onclick="act('media_stop',{})">■ Стоп</button></div><small class="muted">Видео передаётся синхронно на главный экран и телефоны. Если браузер блокирует автовоспроизведение, на экране появится кнопка разрешения.</small>`:'';
  const playlist=Array.isArray(m.items)&&m.items.length>0,nav=playlist?`<div class="media-control-actions"><button class="btn secondary" ${Number(m.index||0)<=0?'disabled':''} onclick="act('round_media_step',{direction:-1})">← Назад</button><span class="muted">${Number(m.index||0)+1} / ${m.items.length}</span><button class="btn primary" ${Number(m.index||0)>=m.items.length-1?'disabled':''} onclick="act('round_media_step',{direction:1})">Далее →</button></div>`:'';
  host.innerHTML=`<div class="media-presentation-active"><div class="media-presentation-top"><div><span class="eyebrow">СЕЙЧАС НА ГЛАВНОМ ЭКРАНЕ</span><b>${esc(m.name||'Медиафайл')}</b><small>${m.type==='video'?'ВИДЕО · '+(playback==='playing'?'ВОСПРОИЗВОДИТСЯ':playback==='paused'?'ПАУЗА':'ОСТАНОВЛЕНО'):'ИЗОБРАЖЕНИЕ · НА ВЕСЬ ЭКРАН'}</small></div>${playlist?'':`<button class="btn danger-glass tiny" onclick="hideScreenMedia()">Скрыть показ ×</button>`}</div>${nav}${controls}${playlist?'<small class="muted">Медиараунд активен. Завершите его через пульт ведущего.</small>':''}</div>`;
}
async function addPerson(){let name=$('personName').value.trim();if(!name)return alert('Введите имя');await act('add_participant',{name});$('personName').value=''}
function renderPeople(){$('scoreCount').textContent=`${S.scoreboard.length} игроков`;let online=S.participants.filter(p=>p.online).length;$('onlineCount').textContent=`${online} онлайн из ${S.participants.length}`;$('participantsList').innerHTML=S.participants.map(p=>`<div class="participant-entry"><span class="online-dot ${p.online?'online':''}"></span><div class="participant-name">${esc(p.name)}<small>${p.online?'Сейчас в игре':'Неактивен'}</small></div>${S.game.format==='team'?`<input class="team-assign-input" id="team-${p.id}" value="${esc(p.group_name||'')}" placeholder="Команда" aria-label="Команда участника"><button class="btn tiny secondary" onclick="assignGroup(${p.id})">Сохранить</button>`:''}<b class="participant-score">${p.score} очк.</b><button class="btn tiny secondary" onclick="score(${p.id},1)">+1</button><button class="icon-btn danger-icon" onclick="removePerson(${p.id})">×</button></div>`).join('')||'<div class="empty-state">Пока никто не подключился</div>';$('scoreTable').innerHTML=S.scoreboard.map((p,i)=>`<div class="score-row"><div class="rank-number">${String(i+1).padStart(2,'0')}</div><div class="score-person"><b>${esc(p.name)}</b><small>${S.game.format==='team'?esc(p.group_name||'Индивидуальный участник'):(p.online?'● Онлайн':'○ Не в сети')}</small></div><div class="score-value">${p.score}<small>очков</small></div><div class="score-controls"><button class="btn tiny secondary" onclick="score(${p.id},-1)">−1</button><button class="btn tiny primary" onclick="score(${p.id},1)">+1</button><button class="btn tiny secondary" onclick="customScore(${p.id})">± Баллы</button><button class="icon-btn danger-icon" onclick="removePerson(${p.id})">×</button></div></div>`).join('')||'<div class="empty-state">Участники ещё не подключились</div>'}
async function assignGroup(id){let group=$('team-'+id)?.value.trim()||'';await act('assign_group',{participant_id:id,group_name:group})}
async function score(id,n){await act('score',{participant_id:id,points:n,reason:'Ручное начисление'})}async function customScore(id){let n=prompt('Сколько баллов начислить? Можно отрицательное число.','2');if(n!==null&&Number.isFinite(Number(n)))await score(id,Number(n))}async function removePerson(id){if(confirm('Удалить участника и его баллы?'))await act('delete_participant',{participant_id:id})}async function clearScores(){if(confirm('Обнулить результаты всех участников текущей игры?'))await act('clear_scores',{})}
async function resetRound(id){const r=S.rounds.find(x=>x.id===id);if(!r)return;if(confirm(`Сбросить раунд «${r.title}»? Будут удалены ответы и баллы этого раунда. Его можно будет запустить заново.`))await act('reset_round',{round_id:id})}
async function resetQuiz(){if(confirm('Полностью сбросить текущий квиз? Будут удалены участники, их ответы и все баллы, реакции и прогресс раундов. Вопросы и загруженные файлы останутся. После сброса игрокам нужно будет подключиться заново.'))await act('reset_quiz',{})}
async function loadAnswers(){try{let a=await api('/api/admin/answers');$('answersList').innerHTML=a.map(x=>`<article class="answer-card"><div><b>${esc(x.name)}</b><small>${esc(x.group_name)} · ${esc(x.question_title||'Вопрос')}</small></div><p>${esc(x.text)}</p><div class="answer-verdict ${x.is_correct===1?'is-correct':x.is_correct===0?'is-wrong':''}">${x.is_correct===1?'✓ Верно · +'+x.awarded_points+' балл.':x.is_correct===0?'✕ Неверно':'Ожидает проверки'}</div><time>${esc(x.created_at)}</time></article>`).join('')||'<div class="empty-state">Ответов пока нет</div>'}catch(e){$('answersList').textContent=e.message}}
function stateSignature(s){const x={...s};delete x.timer_remaining;delete x.server_time;return JSON.stringify(x)}
function connect(){let proto=location.protocol==='https:'?'wss':'ws';let ws=new WebSocket(`${proto}://${location.host}/ws/admin?key=${encodeURIComponent(token)}`);let sig='';ws.onopen=()=>$('connection').innerHTML='<i></i> Онлайн';ws.onmessage=e=>{const next=JSON.parse(e.data),nextSig=stateSignature(next);S=next;syncAdminTimerFromState(next);if(nextSig!==sig){sig=nextSig;render()}};ws.onclose=()=>{$('connection').innerHTML='<i class="offline"></i> Переподключение';setTimeout(connect,2000)}}
if(token){api('/api/admin/games').then(()=>showApp()).catch(()=>{token='';localStorage.removeItem('qc_admin');$('login').classList.remove('hidden');$('app').classList.add('hidden')})}

