Object.assign(window,{doLogin,logout,switchTab,act,refreshQr,savePublicUrl,saveGame,createGame,selectGame,addRound,openRound,saveRound,deleteRound,moveRound,moveQuestion,openQuestion,questionTypeChanged,saveQuestion,deleteQuestion,uploadMedia,detachQuestionMedia,loadMediaLibrary,attachLibraryMedia,deleteLibraryMedia,toggleMediaDrawer,showScreenMedia,hideScreenMedia,addPerson,assignGroup,score,customScore,removePerson,clearScores,loadAnswers,renderDirectorControls,resetRound,resetQuiz,updateRoundMediaField,saveKaraokeSingers,loadSoundOptions,loadRoundSoundOptions,renameLibraryMedia});
